import {parseWeight,coinValue} from './fishing-coins-model.mjs?v=decimal2';
let references=[],glyphs=[];
function surface(w,h){return new OffscreenCanvas(w,h)}
function rgba(source,x=0,y=0,w=source.width,h=source.height,sw=w,sh=h){const c=surface(Math.max(1,Math.round(sw)),Math.max(1,Math.round(sh))),ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,x,y,w,h,0,0,c.width,c.height);return ctx.getImageData(0,0,c.width,c.height).data}
function bounds(mask,w,h){const seen=new Uint8Array(w*h),stack=new Int32Array(w*h),out=[];for(let start=0;start<mask.length;start++){if(!mask[start]||seen[start])continue;let size=1;stack[0]=start;seen[start]=1;let left=w,right=0,top=h,bottom=0;while(size){const i=stack[--size],x=i%w,y=Math.floor(i/w);left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);for(const n of [x?i-1:-1,x<w-1?i+1:-1,y?i-w:-1,y<h-1?i+w:-1])if(n>=0&&mask[n]&&!seen[n]){seen[n]=1;stack[size++]=n;}}out.push({x:left,y:top,w:right-left+1,h:bottom-top+1});}return out}
function findBars(image){const w=image.width,h=image.height,data=rgba(image),mask=new Uint8Array(w*h);for(let i=0;i<mask.length;i++){const k=i*4;mask[i]=Math.max(data[k],data[k+1],data[k+2])<65?1:0;}return bounds(mask,w,h).filter(b=>b.w>w*.15&&b.w<w*.3&&b.h/b.w>.12&&b.h/b.w<.29&&b.y-b.w*1.38>h*.06).sort((a,b)=>Math.round(a.y/8)-Math.round(b.y/8)||a.x-b.x);}
function addSystemGlyphs(){for(const family of ['Arial','sans-serif'])for(const char of '0123456789kg'){const c=surface(100,100),ctx=c.getContext('2d');ctx.font='700 60px '+family;ctx.fillStyle='#fff';ctx.fillText(char,10,70);const a=ctx.getImageData(0,0,100,100).data;let l=100,r=0,t=100,b=0;for(let y=0;y<100;y++)for(let x=0;x<100;x++)if(a[(y*100+x)*4+3]>10){l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);}const p=rgba(c,l,t,r-l+1,b-t+1,16,24);glyphs.push({char,aspect:(r-l+1)/(b-t+1),values:Array.from({length:384},(_,i)=>p[i*4+3])});}}
function readWeight(image,bar){const x=bar.x+Math.round(bar.w*.18),y=bar.y+3,w=bar.w-Math.round(bar.w*.18)-4,h=bar.h-6;if(w<10||h<5)return null;const data=rgba(image,x,y,w,h),mask=new Uint8Array(w*h),cols=new Uint8Array(w);let tallest=0;for(let yy=0;yy<h;yy++)for(let xx=0;xx<w;xx++){const k=(yy*w+xx)*4,r=data[k],g=data[k+1],b=data[k+2];if(Math.min(r,g,b)>145&&Math.max(r,g,b)-Math.min(r,g,b)<95){mask[yy*w+xx]=1;cols[xx]=1;}}
 const spans=[];let start=null;for(let i=0;i<=w;i++){if(cols[i]&&start===null)start=i;else if(!cols[i]&&start!==null){let top=h,bottom=0;for(let yy=0;yy<h;yy++)for(let xx=start;xx<i;xx++)if(mask[yy*w+xx]){top=Math.min(top,yy);bottom=Math.max(bottom,yy);}spans.push({l:start,r:i,t:top,b:bottom+1});tallest=Math.max(tallest,bottom-top+1);start=null;}}
 let text='',worst=0,margin=Infinity;for(let index=0;index<spans.length;index++){const {l,r,t,b}=spans[index];if(b-t<tallest*.34){text+='.';continue;}const c=surface(r-l,b-t),ctx=c.getContext('2d'),a=ctx.createImageData(r-l,b-t);for(let yy=t;yy<b;yy++)for(let xx=l;xx<r;xx++){const k=((yy-t)*(r-l)+xx-l)*4;a.data[k]=a.data[k+1]=a.data[k+2]=255;a.data[k+3]=mask[yy*w+xx]*255;}ctx.putImageData(a,0,0);const normalized=rgba(c,0,0,c.width,c.height,16,24),scores=new Map();for(const g of glyphs){if(index===spans.length-1?g.char!=='g':index===spans.length-2?g.char!=='k':!/[0-9]/.test(g.char))continue;let error=0;for(let i=0;i<384;i++)error+=((normalized[i*4+3]-g.values[i])/255)**2;error=error/384+.15*Math.abs((r-l)/(b-t)-g.aspect);scores.set(g.char,Math.min(scores.get(g.char)??Infinity,error));}const ranked=[...scores].sort((a,b)=>a[1]-b[1]);text+=ranked[0][0];worst=Math.max(worst,ranked[0][1]);if(ranked[1])margin=Math.min(margin,ranked[1][1]-ranked[0][1]);}
 const match=text.match(/^(\d{1,6}\.\d{2})kg$/);return {text,value:match?.[1]??null,worst,margin,readable:!!match&&worst<.24&&margin>.003};}
function quality(card){const votes=new Map();for(let y=5;y<13;y++)for(let x=4;x<12;x++){const k=(y*64+x)*4,r=card[k],g=card[k+1],b=card[k+2];let q;if(r>170&&g>110&&b<130)q=4;else if(r>g*1.3&&b>g*1.3)q=3;else if(b>r*1.3&&g>r*1.2)q=2;else if(r>g*1.3&&r>b*1.15)q=5;if(q)votes.set(q,(votes.get(q)||0)+1);}const top=[...votes].sort((a,b)=>b[1]-a[1])[0];return top?.[1]>40?top[0]:null;}
function fishCost(card,t,size,cx,cy){let art=t.scales.get(size);if(!art){art=rgba(t.bitmap,0,0,t.bitmap.width,t.bitmap.height,size,size);t.scales.set(size,art);}let error=0,count=0;for(let y=4;y<50;y+=2)for(let x=3;x<61;x+=2){if(x>45&&y<22)continue;const xx=x-cx,yy=y-cy;if(xx<0||yy<0||xx>=size||yy>=size)continue;const i=(yy*size+xx)*4,k=(y*64+x)*4;if(art[i+3]<220)continue;error+=((card[k]-art[i])**2+(card[k+1]-art[i+1])**2+(card[k+2]-art[i+2])**2)/3;count++;}return count>=80?error/count:Infinity;}
function identify(card,weight){const q=quality(card),ranked=[];for(const t of references){if(q&&t.fish.quality!==q)continue;if(weight?.value&&parseWeight(weight.value,t.fish).state!=='valid')continue;let best=Infinity,fit;for(const size of [52,56,60,64,68,72,76])for(const cy of [-6,-2,2,6,10])for(const cx of [-6,-2,2,6]){const cost=fishCost(card,t,size,cx,cy);if(cost<best){best=cost;fit={size,cx,cy};}}if(fit)for(const size of [fit.size-2,fit.size,fit.size+2])for(const cy of [fit.cy-2,fit.cy,fit.cy+2])for(const cx of [fit.cx-2,fit.cx,fit.cx+2])best=Math.min(best,fishCost(card,t,size,cx,cy));ranked.push({id:t.fish.id,name:t.fish.name,score:1-Math.min(best/16000,1)});}ranked.sort((a,b)=>b.score-a.score);return {matches:ranked.slice(0,3),readable:ranked[0]?.score>.65&&(!ranked[1]||ranked[0].score-ranked[1].score>.045)};}
function coinCheck(card,value){let best=Infinity;const text=value.toLocaleString('en-US');for(const family of ['Arial','sans-serif'])for(const font of [10,11,12]){const c=surface(90,24),ctx=c.getContext('2d');ctx.font='700 '+font+'px '+family;ctx.textBaseline='top';ctx.lineJoin='round';ctx.strokeStyle='#211c1c';ctx.lineWidth=2.2;ctx.fillStyle='#ffdc57';ctx.strokeText(text,3,3);ctx.fillText(text,3,3);const width=Math.ceil(ctx.measureText(text).width)+6,ref=rgba(c,0,0,width,20);for(let y=48;y<=56;y++)for(let center=34;center<=44;center++){const left=Math.round(center-width/2);let error=0,count=0;for(let yy=0;yy<20;yy++)for(let x=0;x<width;x++){const i=(yy*width+x)*4,xx=left+x,cy=y+yy;if(xx<0||xx>=64||cy>=64||ref[i+3]<220)continue;const k=(cy*64+xx)*4;error+=((card[k]-ref[i])**2+(card[k+1]-ref[i+1])**2+(card[k+2]-ref[i+2])**2)/3;count++;}if(count>30)best=Math.min(best,error/count);}}return best;}
self.onmessage=async({data})=>{try{if(data.type==='load'){glyphs=data.manifest.glyphs;addSystemGlyphs();const atlas=await createImageBitmap(data.atlas);references=[];for(const entry of data.manifest.entries)references.push({fish:data.fish.find(f=>f.id===entry.id),bitmap:await createImageBitmap(atlas,entry.x,entry.y,entry.w,entry.h),scales:new Map()});atlas.close();self.postMessage({type:'ready'});return;}if(data.type==='scan'){const image=data.image,bars=findBars(image),records=[];for(let i=0;i<bars.length;i++){const bar=bars[i],box={x:bar.x,y:Math.round(bar.y-bar.w*1.36),w:bar.w,h:Math.round(bar.w*1.36+bar.h)},card=rgba(image,box.x,box.y,box.w,box.w,64,64),weight=readWeight(image,bar),identity=identify(card,weight),top=identity.matches[0],fish=references.find(t=>t.fish.id===top?.id)?.fish,raw=weight?.value&&fish?parseWeight(weight.value,fish):null,coinError=raw?.state==='valid'?coinCheck(card,coinValue(raw.raw,fish.price)):Infinity;const gap=identity.matches[1]?top.score-identity.matches[1].score:1;records.push({box,bar,weight,...identity,readable:identity.readable||(top?.score>.5&&gap>.2&&weight?.readable&&coinError<6000),coinError});self.postMessage({type:'progress',done:i+1,total:bars.length});}image.close();self.postMessage({type:'result',records});}}catch(error){self.postMessage({type:'error',message:error.message||'Could not read this screenshot.'});}};
